using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"posts/{id}", cancellationToken);

        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks the model to summarize text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences. Defaults to 3.")] int maxSentences = 3)
    {
        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock
                {
                    Text = $"""
                        Please summarize the following text in at most {maxSentences} sentence(s).
                        Be concise and capture the key points.

                        Text:
                        {text}
                        """
                }
            }
        ];
    }
}

